// Package database connects to Postgres and runs work in transactions.
// The queries themselves are generated by sqlc into package db.
package database

import (
	"context"
	"errors"
	"fmt"
	"math"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"platypus/internal/config"
	"platypus/internal/db"
)

// Connect opens a connection pool and checks that the database answers.
func Connect(ctx context.Context, cfg config.Database) (*pgxpool.Pool, error) {
	// The password is set on the parsed config rather than in the connection
	// string, so it can never end up in a parse error.
	connString := fmt.Sprintf("host=%s port=%d dbname=%s user=%s sslmode=%s",
		quote(cfg.Host), cfg.Port, quote(cfg.Name), quote(cfg.Username), cfg.SSLMode)
	if cfg.SSLRootCert != "" {
		connString += " sslrootcert=" + quote(cfg.SSLRootCert)
	}
	poolConfig, err := pgxpool.ParseConfig(connString)
	if err != nil {
		return nil, fmt.Errorf("database settings: %w", err)
	}
	poolConfig.ConnConfig.Password = cfg.Password.Reveal()
	poolConfig.ConnConfig.RuntimeParams["search_path"] = cfg.Schema
	poolConfig.ConnConfig.RuntimeParams["application_name"] = "platypus"
	poolConfig.MaxConnLifetime = time.Hour
	poolConfig.MaxConns = int32(min(cfg.MaxConns, math.MaxInt32)) //nolint:gosec // capped on the line itself

	pool, err := pgxpool.NewWithConfig(ctx, poolConfig)
	if err != nil {
		return nil, fmt.Errorf("connect to database: %w", err)
	}

	pingCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("connect to database %s on %s: %w", cfg.Name, cfg.Host, err)
	}
	return pool, nil
}

// quote makes a value safe for a key=value connection string.
func quote(value string) string {
	return "'" + connStringEscaper.Replace(value) + "'"
}

var connStringEscaper = strings.NewReplacer(`\`, `\\`, `'`, `\'`)

// InTx runs fn in a transaction. It commits when fn returns nil and rolls
// back otherwise.
func InTx(ctx context.Context, pool *pgxpool.Pool, fn func(q *db.Queries) error) error {
	tx, err := pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	if err := fn(db.New(tx)); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}
	return nil
}

// IsNoRows reports whether err means a query returned no row.
func IsNoRows(err error) bool {
	return errors.Is(err, pgx.ErrNoRows)
}

// IsUniqueViolation reports whether err is a duplicate key error.
func IsUniqueViolation(err error) bool {
	return hasSQLState(err, "23505")
}

// IsUniqueViolationOn reports whether err is a duplicate key error on the
// named constraint or index, so callers can say which value clashed.
func IsUniqueViolationOn(err error, name string) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23505" && pgErr.ConstraintName == name
}

// IsForeignKeyViolation reports whether err refers to a row that doesn't exist.
func IsForeignKeyViolation(err error) bool {
	return hasSQLState(err, "23503")
}

func hasSQLState(err error, code string) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == code
}

// WithTryLock runs fn while holding a Postgres advisory lock, unless another
// process holds it already; then fn doesn't run and ran is false. Workers use
// it so a job never runs twice at the same time, even during a rollout.
func WithTryLock(ctx context.Context, pool *pgxpool.Pool, key int64, fn func(context.Context) error) (ran bool, err error) {
	conn, err := pool.Acquire(ctx)
	if err != nil {
		return false, fmt.Errorf("acquire connection: %w", err)
	}
	defer conn.Release()

	var locked bool
	if err := conn.QueryRow(ctx, "SELECT pg_try_advisory_lock($1)", key).Scan(&locked); err != nil {
		return false, fmt.Errorf("take advisory lock: %w", err)
	}
	if !locked {
		return false, nil
	}
	defer func() {
		// Unlock on a fresh context: ctx may be cancelled by now. When that
		// fails, close the connection: Postgres then drops the session and
		// its lock, instead of the pool keeping a connection that holds it.
		unlockCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		if _, unlockErr := conn.Exec(unlockCtx, "SELECT pg_advisory_unlock($1)", key); unlockErr != nil {
			_ = conn.Conn().Close(unlockCtx)
			err = errors.Join(err, fmt.Errorf("release advisory lock: %w", unlockErr))
		}
	}()
	return true, fn(ctx)
}
